with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , PAID_AMOUNT as SETTLEMENT_AMOUNT
        , CLAIM_PASSED as APPROVED_AMOUNT
        , cast(null as varchar) as SETTLEMENT_DATE
        , cast(null as varchar) as SETTLEMENT_TYPE
        , cast(null as varchar) as SETTLEMENT_STATUS
        , 'BJAZ_HM_COINSU_CLM_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_coinsu_clm_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK
        , cast(null as varchar) as SETTLEMENT_AMOUNT
        , APPROVED_AMT as APPROVED_AMOUNT
        , APPROVAL_DATE as SETTLEMENT_DATE
        , cast(null as varchar) as SETTLEMENT_TYPE
        , cast(null as varchar) as SETTLEMENT_STATUS
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CLID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_NO))) as HUB_CLAIM_HK
        , TOTAL_PAYABLE_AMOUNT as SETTLEMENT_AMOUNT
        , TOTAL_APPROVED_AMOUNT as APPROVED_AMOUNT
        , cast(null as varchar) as SETTLEMENT_DATE
        , cast(null as varchar) as SETTLEMENT_TYPE
        , cast(null as varchar) as SETTLEMENT_STATUS
        , 'BJAZ_REMEDINET_CLAIM_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_claim_details') }}
    where (nullif(trim(CLAIM_NO),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK
        , PAYBLE_AMOUNT as SETTLEMENT_AMOUNT
        , APPROVED_AMOUNT as APPROVED_AMOUNT
        , SETTELEMENT_DATE as SETTLEMENT_DATE
        , SETTELEMENT_TYPE as SETTLEMENT_TYPE
        , STATUS as SETTLEMENT_STATUS
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(BJAZ_CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SETTLEMENT_AMOUNT end) as SETTLEMENT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then APPROVED_AMOUNT end) as APPROVED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SETTLEMENT_DATE end) as SETTLEMENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SETTLEMENT_TYPE end) as SETTLEMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SETTLEMENT_STATUS end) as SETTLEMENT_STATUS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when SETTLEMENT_AMOUNT is not null or APPROVED_AMOUNT is not null or SETTLEMENT_DATE is not null or SETTLEMENT_TYPE is not null or SETTLEMENT_STATUS is not null
                     then md5(upper(coalesce(cast(SETTLEMENT_AMOUNT as varchar), '') || '|' || coalesce(cast(APPROVED_AMOUNT as varchar), '') || '|' || coalesce(cast(SETTLEMENT_DATE as varchar), '') || '|' || coalesce(cast(SETTLEMENT_TYPE as varchar), '') || '|' || coalesce(cast(SETTLEMENT_STATUS as varchar), '')))
                end as SAT_CLAIM_SETTLEMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_SETTLEMENT_HASHDIFF is not null
